package io.knowledgebrain.activity;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;
final class SpaceAuthorizationClient {
 record Check(UUID spaceId,String token,String action){@Override public String toString(){return "Check[REDACTED]";}}record Decision(UUID spaceId,UUID principalId,String action,String visibility){}
 private final URI origin;private final HttpClient http;private final String key;private final JsonMapper json=JsonMapper.builder().build();
 SpaceAuthorizationClient(String origin,String trust,String key)throws Exception{this.origin=ActivityHttp.origin(origin);http=ActivityHttp.client(trust);if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Dedicated authority key required");this.key=key;}
 UUID authorize(UUID space,String token,String trace){if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session required");try{var response=ActivityHttp.send(http,HttpRequest.newBuilder(origin.resolve("/internal/space/activity-authorization")).timeout(Duration.ofSeconds(3)).header("Authorization","Bearer "+key).header("traceparent",trace).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(json.writeValueAsBytes(new Check(space,token,"TIMELINE_READ")))).build(),8192);if(Set.of(401,403,404).contains(response.statusCode()))throw new ResponseStatusException(HttpStatus.valueOf(response.statusCode()),"Private Space unavailable");if(response.statusCode()!=200)throw new IllegalStateException();var d=json.readValue(response.body(),Decision.class);if(!space.equals(d.spaceId())||!d.action().equals("TIMELINE_READ")||!d.visibility().equals("PRIVATE"))throw new IllegalStateException();ActivityEvent.id(d.principalId().toString());return d.principalId();}catch(ResponseStatusException e){throw e;}catch(RuntimeException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Space authority unavailable");}}
}
